#!/usr/bin/env python3
"""Source-specific static lowering of the RC6 main-loop region.
Allocated native registers: d0=EAX,d1=EDX,d2=EBX,d7=EBP,a0=ECX,a4=ESI,a5=EDI.
The short-lived a1 cloud cursor shares EDX outside d1's live ranges. No register
bank, runtime decoder, instruction wrappers or C gameplay are generated.
All remaining shell procedures are independently allocated native assembly.
"""
from pathlib import Path
import re
root=Path(__file__).resolve().parent.parent
lines=(root/'reference/src/shell.s').read_text().splitlines()
start=lines.index('asm_loop:');end=lines.index('asm_finish:')
regs={'d0':('eax','ax','al'),'d1':('edx','dx','dl'),'d2':('ebx','bx','bl'),'d3':('ecx','cx','cl'),'d5':('ebp','bp',None),'d4':('ebx','bx','bl'),'d6':('ebx','bx','bl'),'a6':('ebp','bp',None),'a2':('ebp','bp',None),'d7':('ebp','bp',None),'a0':('ecx','cx','cl'),'a1':('edx','dx','dl'),'a4':('esi','si',None),'a5':('edi','di',None),'sp':('esp','sp',None)}
out=['# Native RC6 main loop: source-specific static register allocation.', '# Generated by tools/port-shell-flow.py; original source remains authoritative.', '.text']
branch={'beq':'je','bne':'jne','blo':'jb','bhs':'jae','bhi':'ja','bls':'jbe','blt':'jl','ble':'jle','bmi':'js','bpl':'jns','bra':'jmp'}
serial=0
before=[];after=[]
def emit(s):out.append(' '+s)
def reg(s,size='l'):
 v=regs[s][{'l':0,'w':1,'b':2}[size]]
 if v is None:raise ValueError(('unallocated byte',s))
 return '%'+v
def operand(s,size='l'):
 if s in regs:return reg(s,size)
 if s.startswith('#'):return '$'+s[1:]
 if s=='-(sp)':raise ValueError('predecrement must be handled by caller')
 mpost=re.fullmatch(r'\((\w+)\)\+',s)
 if mpost:
  rr=reg(mpost[1]);after.append('leal '+str({'b':1,'w':2,'l':4}[size])+'('+rr+'),'+rr);return '('+rr+')'
 m=re.fullmatch(r'([^()]*)\((\w+)(?:,(\w+)\.w)?\)',s)
 if m:
  disp,base,index=m.groups()
  if index:
   before.extend(['pushl %ebp','movswl '+reg(index,'w')+',%ebp']);after.insert(0,'popl %ebp')
  return (disp or '0')+'('+reg(base)+( ',%ebp' if index else '')+')'
 if size=='b' and s=='flow_random_carry':return 'flow_random_carry+1'
 if size=='b':
  s=re.sub(r'^(asm_old[127])\+1$',r'\1',s)
 return s
def ismem(x):return not x.startswith(('%','$'))
def flags(x,size):emit('test'+size+' '+(('$'+str((1<<{'b':8,'w':16,'l':32}[size])-1)+','+x) if ismem(x) else x+','+x))
def transfer(src,dst,size,op='mov'):
 if ismem(src) and ismem(dst):
  emit('pushl %eax');ss='4(%esp)' if src=='(%esp)' else src;dd='4(%esp)' if dst=='(%esp)' else dst;emit('mov'+size+' '+ss+','+reg('d0',size));emit(op+size+' '+reg('d0',size)+','+dd);emit('popl %eax')
 else:emit(op+size+' '+src+','+dst)
ranges=[(start,end)]
for a,b in [('asm_contact','asm_spawn_missile'),('asm_view_ship','asm_view_label'),('asm_current_laser','asm_dust_run'),('flow_cargo_keys','uni_state'),('menu_escape','quit_active'),('market_prices_key','market_quantity_paint'),('release_commander','asm_local_chart'),('asm_message','asm_sound_event'),('asm_farof','asm_warp'),('asm_copy_placeholder','asm_view_ship'),('flow_remember','flow_keymap'),('flow_death','flow_status'),('cheat_poll','cheat_actions'),('quit_poll','quit_active_END'),('market_quantity_paint','END'),('asm_dock_keys','asm_clear_view'),('asm_shop_transaction','shop_title'),('asm_save_commander','save_copy'),('asm_navigation_keys','asm_hyper_line'),('asm_commander_page','asm_labels'),('flow_status','flow_equipment_count'),('asm_chart_page','chart_title'),('asm_ambient_begin','asm_encounters'),('asm_fps','asm_dock_keys'),('asm_chart_from_target','asm_flight_messages'),('presentation_cursor','local_index')]:
 ranges.append((next(i for i,l in enumerate(lines) if l.startswith(a+':')),(len(lines) if b=='END' else next(i for i,l in enumerate(lines) if l.startswith(b+':')) if b!='quit_active_END' else next(i for i,l in enumerate(lines) if l.startswith('quit_idle:'))+3)))
for n in [i for a,b in ranges for i in range(a,b)]:
 regs['a1']=('esi','si',None) if lines.index('asm_commander_page:')<=n<lines.index('asm_labels:') else ('edi','di',None) if lines.index('flow_name_start:')<=n<lines.index('flow_pause:') else ('edx','dx','dl')
 raw=lines[n].split(';')[0].strip()
 if not raw or raw.startswith('.'):continue
 if raw.endswith(':'):
  out.extend(['.globl '+raw[:-1],raw]);continue
 # The exact final MT.SUSJB sequence is the sole trap in this region.
 if end-7<=n<end and raw in ('moveq #8,d0','moveq #-1,d1','moveq #1,d3','suba.l a1,a1'):continue
 out.append('# shell.s:'+str(n+1)+' '+raw)
 before=[];after=[]
 op,*rest=raw.split(None,1);args=re.split(r',\s*(?![^()]*\))',rest[0]) if rest else []
 if op=='movem.l':
  assert args[0]=='d0-d7/a0-a6' or args[1]=='d0-d7/a0-a6'
  emit('pushal' if args[1]=='-(sp)' else 'popal');continue
 if op=='swap':
  emit('roll $16,'+reg(args[0]));flags(reg(args[0]),'l');continue
 if op in branch:emit(branch[op]+' '+args[0]);continue
 if op in ('jsr','bsr'):
  if args[0]=='xor_segment':
   emit('pushal');emit('movswl %ax,%eax');emit('movswl %dx,%edx');emit('movswl %bx,%ebx');emit('movswl %cx,%ecx');emit('movl _elite_screen,%esi');emit('call xor_segment');emit('popal')
  elif args[0] in ('asm_keyrow','asm_dust_run'):
   emit('pushl %eax');emit('call '+args[0]);emit('leal 4(%esp),%esp')
  elif '(' in args[0]:
   target=operand(args[0]);
   for b in before:emit(b)
   emit('pushl %eax');emit('leal '+target+',%eax');emit('call *%eax');emit('popl %eax')
   for a in after:emit(a)
  else:emit('call '+args[0])
  continue
 if op=='rts':emit('ret');continue
 if op=='trap':
  assert args==['#1'] and n>=end-4
  emit('pushl $1');emit('call _platform_yield50');emit('leal 4(%esp),%esp');continue
 if op=='dbra':
  serial+=1;rr=reg(args[0],'w');label=args[1]
  emit('pushfl');emit('decw '+rr);emit('cmpw $-1,'+rr);emit('je flow_db_done_'+str(serial));emit('popfl');emit('jmp '+label);out.append('flow_db_done_'+str(serial)+':');emit('popfl');continue
 if op=='sne':
  serial+=1;dst=operand(args[0],'b');emit('je flow_scc_zero_'+str(serial));emit('movb $255,'+dst);emit('jmp flow_scc_end_'+str(serial));out.append('flow_scc_zero_'+str(serial)+':');emit('movb $0,'+dst);out.append('flow_scc_end_'+str(serial)+':');continue
 if op=='bset':
  dst=operand(args[1],'l');emit('orl $'+str(1<<int(args[0][1:]))+','+dst);continue
 if op=='btst':
  if not args[0].startswith('#'):
   emit('btl '+reg(args[0])+','+reg(args[1]));emit('pushl %eax');serial+=1;emit('movb $0,%al');emit('jnc flow_bit_'+str(serial));emit('movb $1,%al');out.append('flow_bit_'+str(serial)+':');emit('testb %al,%al');emit('popl %eax');continue
  bit=int(args[0][1:],0);sz='l' if args[1] in regs else 'b';dst=operand(args[1],sz)
  emit('test'+sz+' $'+str(1<<(bit%(32 if sz=='l' else 8)))+','+dst);continue
 if op=='pea':
  if args[0]=='0x20000':emit('pushl _elite_screen')
  elif '(' not in args[0]:emit('pushl $'+args[0])
  else:
   a=operand(args[0]);assert not before
   emit('pushl %eax');emit('leal '+a+',%eax');emit('xchgl %eax,(%esp)')
  continue
 if op=='lea' and args[0]=='0x22800':
  emit('movl _elite_screen,'+reg(args[1]));emit('leal 10240('+reg(args[1])+'),'+reg(args[1]));continue
 if op=='lea':
  src,dst=args
  if src=='0x20000':emit('movl _elite_screen,'+reg(dst));continue
  a=operand(src)
  for b in before:emit(b)
  emit('leal '+a+','+reg(dst))
  for a in after:emit(a)
  continue
 if op=='moveq':
  dst=reg(args[1]);emit('movl $'+args[0][1:]+','+dst);flags(dst,'l');continue
 if raw=='move.l #0x20000,a0' and n>=lines.index('presentation_cursor:'):continue
 if raw=='move.l #0x27c00,a0':
  emit('movl _elite_screen,%ecx');emit('leal 31744(%ecx),%ecx');continue
 base,sz=op.split('.')
 if raw=='move.b (a6)+,d0':
  emit('pushl %ebp');emit('movzwl asm_page_item,%ebp');emit('movb asm_cargo(%ebp),%al');emit('popl %ebp');flags('%al','b');continue
 if sz=='w' and base=='move' and args[1] in ('asm_enc_output','asm_enc_output+2'):
  v=int(args[0][1:]);emit('movw $'+str(int.from_bytes(v.to_bytes(2,'big'),'little'))+','+args[1]);flags(args[1],'w');continue
 if sz=='w' and base=='move' and args[1]=='_commander_filename':
  emit('pushl %eax');transfer(operand(args[0],'w'),'%ax','w');emit('xchgb %al,%ah');emit('movw %ax,_commander_filename');emit('popl %eax');continue
 if base=='divu':
  assert sz=='w'
  serial+=1;dst=reg(args[1]);offset={'%eax':28,'%ecx':24,'%edx':20,'%ebx':16,'%ebp':8,'%esi':4,'%edi':0}[dst]
  emit('pushal');emit('movzwl '+operand(args[0],'w')+',%ecx' if not args[0].startswith('#') else 'movl $'+args[0][1:]+',%ecx');emit('movl '+str(offset)+'(%esp),%eax');emit('xorl %edx,%edx');emit('divl %ecx');emit('cmpl $65535,%eax');emit('ja flow_div_over_'+str(serial));emit('shll $16,%edx');emit('orl %edx,%eax');emit('movl %eax,'+str(offset)+'(%esp)');emit('popal');flags(reg(args[1],'w'),'w');emit('jmp flow_div_end_'+str(serial));out.append('flow_div_over_'+str(serial)+':');emit('popal');emit('pushfl');emit('andl $-2,(%esp)');emit('orl $2048,(%esp)');emit('popfl');out.append('flow_div_end_'+str(serial)+':');continue
 if base in ('adda','suba'):
  src,dst=args
  if src==dst and base=='suba':emit('movl $0,'+reg(dst));continue
  if base=='adda' and sz=='w':
   emit('pushl %ebp');emit('movswl '+reg(src,'w')+',%ebp');emit('leal ('+reg(dst)+',%ebp),'+reg(dst));emit('popl %ebp');continue
  assert base=='adda' and sz=='l' and src in regs
  emit('leal ('+reg(dst)+','+reg(src)+'),'+reg(dst));continue
 if sz=='l' and base=='move' and args==['asm_commander','d0']:
  emit('movl asm_commander,%eax');emit('xchgb %al,%ah');emit('roll $16,%eax');emit('xchgb %al,%ah');flags('%eax','l');continue
 if sz=='l' and base=='move' and args==['#0x45514132','save_buffer']:
  emit('movl $0x32415145,save_buffer');flags('save_buffer','l');continue
 if sz=='l' and base=='move' and args==['d0','save_buffer+4']:
  emit('pushl %eax');emit('xchgb %al,%ah');emit('roll $16,%eax');emit('xchgb %al,%ah');emit('movl %eax,save_buffer+4');emit('popl %eax');flags('%eax','l');continue
 if sz=='l' and base=='cmp' and args[1]=='save_buffer':
  v=int(args[0][1:],0);emit('cmpl $'+str(int.from_bytes(v.to_bytes(4,'big'),'little'))+',save_buffer');continue
 if sz=='l' and base=='cmp' and args==['save_buffer+4','d0']:
  emit('pushl %edx');emit('movl save_buffer+4,%edx');emit('xchgb %dl,%dh');emit('roll $16,%edx');emit('xchgb %dl,%dh');emit('cmpl %edx,%eax');emit('popl %edx');continue
 if base=='move' and args[1]=='-(sp)':
  src=operand(args[0],sz)
  if args[0]=='#0x20000':src='_elite_screen'
  if sz=='l':emit('pushl '+src);flags('(%esp)','l')
  else:emit('leal -2(%esp),%esp');transfer(src,'(%esp)','w');flags('(%esp)','w')
  continue
 if base=='move' and args[0]=='(sp)+':
  dst=operand(args[1],sz);transfer('(%esp)',dst,sz);emit('leal '+('2' if sz=='w' else '4')+'(%esp),%esp');flags(dst,sz);continue
 if base in ('addq','subq') and (args[1]=='sp' or args[1].startswith('a') and args[1] in regs):
  v=int(args[0][1:],0)*(1 if base=='addq' else -1);rr=reg(args[1]);emit('leal '+str(v)+'('+rr+'),'+rr);continue
 if base in ('addq','subq') and args[1]=='sp':
  v=int(args[0][1:],0)*(1 if base=='addq' else -1);emit('leal '+str(v)+'(%esp),%esp');continue
 if base=='clr' and args==['-(sp)']:
  assert sz=='l';emit('pushl $0');flags('(%esp)','l');continue
 if base in ('clr','tst','not'):
  dst=operand(args[0],sz)
  for b in before:emit(b)
  if base=='not':emit('not'+sz+' '+dst)
  if base=='clr':emit('mov'+sz+' $0,'+dst)
  flags(dst,sz)
  for a in after:emit(a)
  continue
 if base=='mulu':
  src,dst=args;assert sz=='w' and src.startswith('#')
  emit('movzwl '+reg(dst,'w')+','+reg(dst));emit('imull $'+src[1:]+','+reg(dst));flags(reg(dst),'l');continue
 src=operand(args[0],sz);dst=operand(args[1],sz)
 for b in before:emit(b)
 if base=='move':
  if args[1].startswith('a') and args[1] in regs:
   assert sz=='l';transfer(src,reg(args[1]),sz)
  else:transfer(src,dst,sz);flags(dst,sz)
 elif base in ('addq','subq','add','sub','and','or','eor','cmp'):
  transfer(src,dst,sz,{'addq':'add','subq':'sub','eor':'xor'}.get(base,base))
 elif base in ('lsl','lsr'):emit(('shl' if base=='lsl' else 'shr')+sz+' '+src+','+dst)
 else:raise ValueError((n+1,raw))
 for a in after:emit(a)
(root/'src/shell_flow.s').write_text('\n'.join(out)+'\n')
